package net.civeira.phylax.features.document.snippetversion.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class SubjectVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property subject of snippet version ")
  void test_subject_v_o_builder() {
    Assertions.assertFalse(SubjectVO.nullValue().getSubject().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(SubjectVO.tryFrom(null).getSubject().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", SubjectVO.from("one").getSubject().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> SubjectVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", SubjectVO.from("one").toString());
  }
}
